/* Survives any class-name rewrite */
main > article { max-width: 42rem; }
header nav a { text-decoration: none; }

/* The classic grid look is CSS, not HTML */
table { border-collapse: collapse; }
td, th { border: 1px solid #999; padding: 0.4rem; }

/* Sticky header — requires a real thead */
thead th {
  position: sticky;
  top: 0;
  background: white;
}

// Feature detection for any input type
const i = document.createElement('input');
i.setAttribute('type', 'month');
const supported = i.type === 'month'; // false → fell back to text
